INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 2, 'theory', 'Quiz: Node.js and io.js');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 0, 'Why did Ryan Dahl build Node.js around non-blocking I/O?', '["Because JavaScript cannot run in threads", "Classic servers spent a thread on every connection, and threads waited idly for disk and network", "Because browsers have no I/O", "To avoid using the V8 engine"]', 1, 'A single-threaded event loop serves thousands of slow clients: an operation is started, a callback is registered, and control returns to the loop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 1, 'What is libuv?', '["A cross-platform library that waits for OS events (epoll, kqueue, IOCP) and implements the event loop", "The Node.js package manager", "Google''s JavaScript engine", "The CommonJS module standard"]', 0, 'Originally libev and libeio were used; libuv appeared to support Windows as well.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 2, 'What caused the io.js fork in December 2014?', '["A technical dispute over how V8 works", "A move to the Rust language", "Discontent with closed governance (one company), rare releases and an outdated V8", "A ban on using npm"]', 2, 'Developers wanted open governance by a technical committee, fast semver releases and a fresh V8 with new language features.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 3, 'How did the io.js story end?', '["io.js was shut down with no consequences", "io.js displaced Node.js and kept its own name", "Node.js came under Microsoft''s control", "The projects merged: in September 2015 Node.js 4.0 came out on the io.js codebase"]', 3, 'The version jumped from 0.12 straight to 4: versions 1–3 were already taken by io.js. Open governance and regular releases became the basis of Node.js.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 4, 'What is the module format Node.js has used since early versions (require and module.exports) called?', '["ES modules", "CommonJS", "AMD", "UMD"]', 1, 'require loads a file, and module.exports hands out what is needed; ES modules (import/export) came later and are natively supported in Node.js.');
